/**
 * Schema for the two data files.
 *
 * places.json   — curated by hand. Names, codes, descriptions. Never written
 *                 by a script; the importer only ever reads it.
 * timeline.json — generated by scripts/import-timeline.mjs from a Google
 *                 Timeline export. Fully regenerated on every import, so it
 *                 must never hold anything a human typed.
 *
 * They join on Place.id.
 */

export interface Coords {
  lat: number;
  lng: number;
}

export type RegionType = "state" | "union_territory" | "emirate" | "city" | "province";

/**
 * Review lifecycle for a curated place.
 *
 *   undefined  published — the normal state, rendered everywhere
 *   UNMARKED   auto-added by a human from an importer report and not yet
 *              written up. Still rendered, but badged, so it is visible on the
 *              globe while being reviewed.
 *   ARCHIVE    not a destination. Contributes to no total, carries no prose,
 *              and is never interactive — hovering one shows nothing, because
 *              it has nothing to say about the journey. It is only the shape
 *              of how a journey was assembled: a fuel stop, a roadside pause.
 *              Hidden unless the Verbose layer is on, where it draws as a
 *              small dot. The importer still snaps visits to it, so a place
 *              already triaged stays out of the unmatched report instead of
 *              resurfacing on every run.
 */
export type PlaceStatus = "UNMARKED" | "ARCHIVE";

export interface Place {
  id: string;
  name: string;
  code: string;
  coords: Coords;
  desc: string;
  status?: PlaceStatus;
}

export interface Region {
  id: string;
  name: string;
  type: RegionType;
  country: { name: string; code: string };
  center: Coords;
  places: Place[];
}

export interface PlacesFile {
  version: 2;
  type: "Places";
  regions: Region[];
}

/** Google's activity vocabulary, kept verbatim so the importer needs no mapping. */
export type TravelMode =
  | "flying"
  | "in train"
  | "in subway"
  | "in tram"
  | "in bus"
  | "in passenger vehicle"
  | "motorcycling"
  | "cycling"
  | "walking";

/**
 * A leg endpoint. `placeId` non-null means the endpoint snapped to a curated
 * place and lat/lng are that place's coordinates — no raw position is exposed.
 * Null means it fell outside the snap radius and lat/lng are rounded to the
 * precision recorded in `TimelineFile.source.precision.pathDecimals`.
 */
export interface LegEndpoint {
  placeId: string | null;
  lat: number;
  lng: number;
}

export interface Leg {
  id: string;
  mode: TravelMode;
  /**
   * "inferred" means the importer overrode Google's label because the distance
   * made it impossible — an 11,000km "train" is a flight.
   */
  modeSource: "google" | "inferred";
  /** Local calendar date, no clock time. */
  date: string;
  distanceKm: number;
  arcAlt: number;
  from: LegEndpoint;
  to: LegEndpoint;
}

/** A coarse route polyline; points are [lat, lng], rounded. */
export interface PathLine {
  id: string;
  date: string;
  /**
   * Attributed by the importer from the activity records this trace overlaps
   * in time. Null when nothing overlapped.
   */
  mode: TravelMode | null;
  points: [number, number][];
}

export interface PlaceStats {
  visits: number;
  days: number;
  firstSeen: string;
  lastSeen: string;
}

export interface TimelineFile {
  version: 2;
  type: "Timeline";
  source: {
    export: string;
    coverage: { from: string; to: string };
    precision: { pathDecimals: number; snapKm: number; minLegKm: number };
    inputSha256?: string;
  };
  places: Record<string, PlaceStats>;
  /**
   * Region-level totals computed independently by the importer, NOT summed
   * from `places`. A day spent in two places in one region is one day here.
   */
  regions: Record<string, PlaceStats>;
  legs: Leg[];
  paths: PathLine[];
  modeStats: Record<string, { count: number; km: number }>;
}

// --- view models handed to the renderer -------------------------------------

export interface PlaceView extends Place {
  regionId: string;
  regionName: string;
  country: string;
  stats: PlaceStats | null;
}

export interface RegionView {
  /** three-globe label text */
  text: string;
  lat: number;
  lng: number;
  size: number;
  id: string;
  region: string;
  regionType: RegionType;
  country: string;
  countryCode: string;
  /** Place the region marker is drawn on — its most-visited place. */
  anchorId: string;
  cities: string[];
  places: PlaceView[];
  stats: PlaceStats | null;
  desc: string;
}

export interface PlaceMarker {
  text: string;
  city: string;
  status?: PlaceStatus;
  country: string;
  lat: number;
  lng: number;
  desc: string;
  size: number;
  stats: PlaceStats | null;
  /** 0..1 opacity — visit count read as accumulated light. */
  exposure: number;
  /** Warm when recent, cooling with age. */
  color: string;
  parentRegion: RegionView;
}
